#!/usr/bin/env python3
"""Editorially selected Dongyangsa questions; exact source lines resolve at build time.

Every call below is an independently selected question, not a cross-type template.
Only source lookup, IDs, choice rotation, and JSON serialization are automated.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SUBJECT = "dongyangsa"
NOTES = {n["id"]: n for n in json.loads((ROOT / "public/data/subjects/dongyangsa/notes.json").read_text())}
QUESTIONS = []
COUNTS = {"mc": 0, "short": 0, "blank": 0, "essay": 0}


def evidence(page, needle):
    page = f"dongyangsa-textbook-page-{page}"
    matches = list(dict.fromkeys(line for line in NOTES[page]["text"].splitlines() if needle in line))
    if len(matches) != 1:
        raise ValueError(f"Expected one source line: {page}: {needle!r} ({len(matches)} matches)")
    return {"page": page, "quote": matches[0]}


def base(kind, page, needle, prompt, answer, explain, skill):
    COUNTS[kind] += 1
    return {"id": f"dongyangsa-ext-{kind}-{COUNTS[kind]:03d}", "type": kind, "skill": skill,
            "prompt": prompt, "answer": answer, "explain": explain, "evidence": [evidence(page, needle)]}


def mc(page, needle, prompt, correct, distractors, explain, skill="fact", additional=()):
    row = base("mc", page, needle, prompt, 0, explain, skill)
    # Distractors are authored with their reasons, separated by ::.
    pairs = [(correct, explain)] + [tuple(d.split("::", 1)) for d in distractors]
    rotation = (COUNTS["mc"] - 1) % 4
    pairs = pairs[-rotation:] + pairs[:-rotation] if rotation else pairs
    row.update(choices=[p[0] for p in pairs], answer=rotation,
               choiceExplanations=[p[1] for p in pairs])
    row["evidence"].extend(evidence(p, n) for p, n in additional)
    QUESTIONS.append(row)


def short(page, needle, prompt, answer, explain, skill="fact", aliases=()):
    row = base("short", page, needle, prompt, answer, explain, skill)
    row["acceptedAnswers"] = list(aliases)
    QUESTIONS.append(row)


def blank(page, needle, answer, passage=None):
    ev = evidence(page, needle)
    passage = passage or ev["quote"]
    assert passage in ev["quote"]
    row = base("blank", page, needle, passage.replace(answer, "_____"), answer,
               "원문에서 빠진 핵심어는 " + answer + "이다. " + ev["quote"], "source-analysis")
    row["passage"] = passage
    QUESTIONS.append(row)


def essay(title, prompt, criteria, skill="comparison"):
    # Each tuple names a separate scoring element with its own exact quotation.
    rubric = []
    all_evidence = []
    for index, (page, needle, label, ok, reject) in enumerate(criteria):
        ev = evidence(page, needle)
        maximum = [3, 3, 4][index]
        rubric.append({"id": f"r{index + 1}", "label": label, "max": maximum, "ok": ok,
                       "allowedScores": list(range(maximum + 1)), "acceptedConcepts": [ok],
                       "checkpoints": [label], "rejectConditions": [reject], "evidence": [ev],
                       "scoring": "요구한 핵심 의미를 정확히 설명하면 만점, 일부만 설명하면 그 충족 정도에 따라 부분점수. 의미가 같은 표현을 인정한다. 누락·모순은 해당 기준에서만 감점하고 다른 기준의 충족을 취소하지 않는다."})
        if ev not in all_evidence:
            all_evidence.append(ev)
    page, needle = criteria[0][:2]
    answer = " ".join(c[3] for c in criteria)
    row = base("essay", page, needle, prompt, answer, "비교·설명의 기준은 " + ", ".join(c[2] for c in criteria) + "이다.", skill)
    row.update(title=title, rubric=rubric, evidence=all_evidence)
    QUESTIONS.append(row)


