short(273,"샌프란시스코 강화 조약(1951)","1951년 일본의 국제 사회 복귀와 관련하여 체결한 강화 조약은?","샌프란시스코 강화 조약","이 조약은 전쟁의 처리와 일본의 영토 포기 등의 내용을 담았다.",aliases=("샌프란시스코 조약",))
short(276,"오키나와현의 일본 반환(1972. 5.)","미국의 통치를 받던 오키나와가 일본에 반환된 해는?","1972","미·일 협상에 따라 오키나와 반환이 이행되었다.",aliases=("1972년",))
short(276,"중국 : 대일 배상 청구권 포기","1972년 중·일 공동 성명에서 중국이 포기한 대일 권리는?","배상 청구권","일본의 전쟁 책임·반성 표명과 함께 중국의 대일 배상 청구권 포기가 제시된다.",aliases=("대일 배상 청구권",))
short(278,"도시 : 하라파·모헨조다로 등의 건설","인더스 문명의 대표 도시 중 모헨조다로와 함께 제시된 도시는?","하라파","하라파와 모헨조다로는 인더스 문명의 대표 도시이다.")
short(278,"혈통 신분에 따른 사회적 지위 및 생활 규정","인도에서 혈통에 따른 사회적 지위와 생활을 규정한 신분 제도의 명칭은?","카스트제","교재는 카스트제를 혈통 신분에 따른 사회 규범으로 설명한다.",aliases=("카스트",))
short(280,"로마, 동남아시아와의 해상 무역을 통하여 번영","남인도 데칸 고원에서 성장하며 로마·동남아시아와의 해상무역으로 번영한 왕조는?","안드라 왕조","교재는 안드라 왕조의 번영을 해상무역과 연결한다.",aliases=("안드라",))
short(280,"찬드라 굽타 1세가 건국","4세기 초 굽타 왕조를 건국한 인물은?","찬드라 굽타 1세","굽타 왕조는 북인도 대부분을 차지하며 발전하였다.",aliases=("찬드라굽타 1세",))
short(282,"바부르의 카불 점령(1504)","카불에 기반을 마련하고 1526년 델리를 점령해 무굴 제국을 세운 인물은?","바부르","바부르는 무굴 제국의 창건자이다.")
short(282,"이교도가 납부하는 인두세 폐지","무굴 시대 비무슬림에게 부과된 인두세로, 아크바르가 폐지한 세금은?","지즈야","아크바르의 지즈야 폐지는 종교적 관용 정책의 사례다.")
short(283,"영국 동인도회사의 벵골 지방 통치권·조세 징수권","플라시 전투 이후 영국 동인도회사가 통치권·조세 징수권을 확보한 인도의 지역은?","벵골","영국은 벵골을 기반으로 인도 지배를 확대했다.")
short(285,"국민회의 새로운 의장으로 선출(1929)","1929년 국민회의 의장으로 선출되어 완전 독립을 목표로 선언한 인물은?","네루","네루는 완전 독립을 목표로 불복종 운동을 독려했다.",aliases=("자와할랄 네루",))
short(287,"외왕내제(황제 자칭·연호 사용)","베트남 딘 왕조가 대외적으로 왕의 형식을 취하면서 국내에서 황제와 연호를 사용하는 방식을 무엇이라 하는가?","외왕내제","외왕내제는 중국과의 통교 형식과 국내 군주 권위가 병존한 방식이다.")
short(289,"명의 지배 : 영락제의 침입으로 직접 지배","15세기 초 베트남을 침략하여 직접 지배한 명의 황제는?","영락제","명은 영락제 때 베트남을 직접 지배하며 학교를 세우고 성리학을 보급했다.")
short(294,"동유 운동 : 량치차오와의 만남 직후","판보이쩌우가 베트남 학생들의 일본 유학을 추진한 운동은?","동유 운동","일본에서 근대 문물을 배우도록 한 유학 운동이다.",aliases=("동유운동", "동두 운동"))
short(296,"도이머이(Doi Moi) 정책의 추진(1986)","베트남이 1986년 시작한 혼합 경제와 외자 유치를 추진하는 개혁 정책은?","도이머이","도이머이는 농업 투자와 교역·외자 유치 확대를 포함했다.",aliases=("도이머이 정책",))
short(301,"카르티니 : 여성 교육 운동 헌신","인도네시아에서 여성 교육 운동에 헌신하고 사후 학교 설립에 영향을 준 인물은?","카르티니","카르티니의 활동은 여성 교육과 권리 의식 성장의 사례다.")
short(303,"8888 민주화 항쟁 : 네윈 사임 요구","1988년 미얀마에서 네윈의 사임 등을 요구한 민주화 시위를 통상 무엇이라 하는가?","8888 민주화 항쟁","아웅산 수치 등이 참여한 미얀마 민주화 운동이다.",aliases=("8888항쟁", "8888 항쟁", "8888민주화운동"))

